from flask import Flask, render_template, request
import subprocess

app = Flask(__name__)

@app.route('/notes')
def notes():
    return render_template('notes.html')

@app.route('/recording', methods=['POST'])
def recording():
    recording_id = request.form['id']

    command = f"ffmpeg -v error -i recording_{recording_id}.txt -c:a aac -b:a 128k recording_{recording_id}.mp3"
    subprocess.run(command, shell=True)

    return render_template('success.html')

if __name__ == '__main__':
    app.run()
